// Optional AI behavior is initialized only after the offline dashboard is ready.
let briefAbort=null,briefEpoch=0,briefHistory=[],briefHistoryContext='',lastBrief='';
const briefDialog=$('briefDialog');
function briefContext(){const analysis=analyzeRange(datasets[material],$('from').value,$('to').value);const context=buildBriefContext({material:materials[material],series:material,from:$('from').value,to:$('to').value,rows:analysis.rows.filter(r=>r.index!=null),budget:$('briefBudget').value.trim()?Number($('briefBudget').value):null,buyBy:$('briefDate').value,notes:$('briefNotes').value.trim()});context.comparisonWindowMonths=analysis.windowMonths;context.selectedRangeStatistics={averageMonthlyChange:analysis.monthly,averageComparisonChange:analysis.comparison,volatilityPP:analysis.rangeVolatility};context.method+=' For this selection, history.yoy is a '+analysis.windowMonths+'-month comparison and history.vol uses '+analysis.windowMonths+' monthly returns. Labels adapt for selections shorter than 12 months. Selected-range volatility is the sample SD across selected monthly changes.';return context}
function showBriefContext(){const ready=!!datasets[material]&&$('from').value&&$('to').value;$('briefSelection').textContent=ready?materials[material]+' · '+$('from').value+' → '+$('to').value:'Load a valid chart range first.';try{const c=briefContext();$('briefPreview').textContent=JSON.stringify(c,null,2);$('briefCount').textContent=c.observations+' monthly observations plus your project details and conversation will be sent.'}catch(error){$('briefPreview').textContent=error.message;$('briefCount').textContent=error.message}$('briefNetwork').textContent=navigator.onLine===false?'Offline · charts work; connect to generate a brief.':'Online AI · Gemini API key required'}
function openBrief(){showBriefContext();briefDialog.showModal();($('briefKey').value?$('briefQuestion'):$('briefKey')).focus()}
$('buildBrief').onclick=openBrief;
for(const id of ['briefBudget','briefDate','briefNotes'])$(id).oninput=showBriefContext;
window.addEventListener('materialdesk:context',()=>{if(briefDialog.open)showBriefContext()});window.addEventListener('online',showBriefContext);window.addEventListener('offline',showBriefContext);
function setBriefBusy(busy){$('briefGenerate').disabled=busy;for(const id of ['briefModel','briefKey','briefBudget','briefDate','briefNotes','briefQuestion'])$(id).disabled=busy;$('briefCancel').hidden=!busy}
briefDialog.addEventListener('close',()=>briefAbort?.abort());$('briefCancel').onclick=()=>briefAbort?.abort();
$('briefForget').onclick=()=>{briefEpoch++;briefAbort?.abort();$('briefKey').value='';briefHistory=[];briefHistoryContext='';lastBrief='';$('briefMessages').replaceChildren();$('briefStatus').textContent='Key and brief cleared.';$('briefDownload').disabled=true;$('briefKey').focus()};
function appendBriefMessage(label,text){const section=document.createElement('section');section.className='brief-message';const title=document.createElement('h3');title.textContent=label;const body=document.createElement('div');body.className='brief-text';body.textContent=text;section.append(title,body);$('briefMessages').append(section);return body}
$('briefDownload').onclick=()=>{if(lastBrief)downloadFile('Material Desk purchasing brief.txt',lastBrief,'text/plain')};
$('briefForm').onsubmit=async event=>{event.preventDefault();if(briefAbort)return;const status=$('briefStatus');status.textContent='';if(!validate()){status.textContent='Correct the chart date range before generating a brief.';return}if(!$('briefKey').value.trim()){status.textContent='Enter your Gemini API key. The charts do not require a key.';$('briefKey').focus();return}if(navigator.onLine===false){status.textContent='You are offline. Connect to generate a brief; all charts remain available.';return}let context;try{context=briefContext()}catch(error){status.textContent=error.message;return}const question=$('briefQuestion').value.trim()||'Build a purchasing brief for this material and project. Ask for missing constraints before recommending a purchase schedule.';const signature=JSON.stringify(context);const prior=briefHistoryContext===signature?briefHistory:[];const messages=[...prior,{role:'user',text:question}].slice(-7);const epoch=briefEpoch;const abort=new AbortController();briefAbort=abort;let timedOut=false;const timer=setTimeout(()=>{timedOut=true;abort.abort()},90000);setBriefBusy(true);status.textContent='Sending the previewed context directly to Gemini…';let reply;try{const result=await requestBrief({key:$('briefKey').value,model:$('briefModel').value.trim(),context,messages},{signal:abort.signal});if(epoch!==briefEpoch)return;const contextLabel=context.material+' · '+context.selectedRange.from+' → '+context.selectedRange.to;appendBriefMessage('Your request · '+contextLabel,question);reply=appendBriefMessage('Gemini brief · '+contextLabel,result.text);briefHistory=[...messages,{role:'model',text:result.text}].slice(-6);briefHistoryContext=signature;lastBrief='MATERIAL DESK / PURCHASING BRIEF\n'+contextLabel+'\nSource: '+context.source+'\nGenerated: '+new Date().toISOString()+'\nModel: '+$('briefModel').value.trim()+'\n\n'+result.text+'\n\nHistorical context, not a forecast. Review illustrative contract wording with a qualified professional.';$('briefDownload').disabled=false;$('briefQuestion').value='';status.textContent=result.truncated?'The model reached its output limit. Ask a follow-up to continue.':'Brief ready. Review its sources and assumptions. Project or chart changes start a fresh AI context.';reply.scrollIntoView({block:'nearest',behavior:'smooth'})}catch(error){if(epoch!==briefEpoch)return;status.textContent=error.name==='AbortError'?(timedOut?'Request timed out. Please retry.':'Request cancelled.'):error.message}finally{clearTimeout(timer);if(briefAbort===abort)briefAbort=null;setBriefBusy(false)}};
window.addEventListener('pagehide',()=>{briefEpoch++;briefAbort?.abort();$('briefKey').value='';briefHistory=[];lastBrief='';$('briefMessages').replaceChildren();$('briefDownload').disabled=true});

$('buildBrief').disabled=!datasets[material];$('briefModel').value=DEFAULT_BRIEF_MODEL;
